                          if (!canAfford) return;
                          setGameState((prev) => ({ ...prev, gold: prev.gold - cost }));
                          setLudusUpgrades((prev) => ({ ...prev, medicalBay: prev.medicalBay + 1 }));
                          gameAudio.playPowerupChime();
